import 'package:flutter/material.dart';

/// The type of recommendation generated by the engine.
enum RecommendationType {
  /// Air quality is safe for outdoor exercise right now.
  safeNow,

  /// Air quality is not safe now, but a better window exists later.
  bestWindow,

  /// Air quality is poor all day — stay indoors.
  stayIndoors,

  /// Rain is expected — bring an umbrella.
  umbrella,
}

/// How urgent or severe the recommendation is.
enum RecommendationSeverity { good, moderate, warning, danger }

/// A single, actionable recommendation produced by the engine.
class Recommendation {
  const Recommendation({
    required this.type,
    required this.severity,
    required this.icon,
    required this.title,
    required this.headline,
    required this.body,
    required this.aqi,
    this.bestWindowStart,
    this.bestWindowEnd,
    this.bestWindowAqi,
    this.precipitationProbability,
  });

  final RecommendationType type;
  final RecommendationSeverity severity;

  /// Icon to show on the Action Card (Material icon).
  final IconData icon;

  /// Short status label, e.g. "Safe to Run" or "Stay Indoors".
  final String title;

  /// One-line summary, e.g. "Best window: Today at 6 PM (AQI 45)".
  final String headline;

  /// Longer advice text.
  final String body;

  /// The AQI value this recommendation is based on.
  final int aqi;

  /// Start of the recommended outdoor window (null if stayIndoors).
  final DateTime? bestWindowStart;

  /// End of the recommended outdoor window.
  final DateTime? bestWindowEnd;

  /// Average AQI during the best window.
  final int? bestWindowAqi;

  /// Precipitation probability for umbrella recommendations.
  final double? precipitationProbability;
}
